// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue, uniqueSuffix } from '@skyramp/skyramp';
import { createNewsletter, deleteNewsletter, getNewsletter } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:2368");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Ghost " + process.env.SKYRAMP_TEST_TOKEN;
    }

    const newslettersPostResponse = await createNewsletter(client, headers, "Skyramp Delete Lifecycle", 201);
    expect(getResponseValue(newslettersPostResponse, "newsletters.0.description"), 'description').toBe("Created by the Skyramp newsletter delete lifecycle test");
    expect(getResponseValue(newslettersPostResponse, "newsletters.0.status"), 'status').toBe("active");
    expect(getResponseValue(newslettersPostResponse, "newsletters.0.visibility"), 'visibility').toBe("members");
    expect(getResponseValue(newslettersPostResponse, "newsletters.0.subscribe_on_signup"), 'subscribe_on_signup').toBe(true);
    expect(getResponseValue(newslettersPostResponse, "newsletters.0.sort_order"), 'sort_order').toBeGreaterThanOrEqual(0);
    expect(getResponseValue(newslettersPostResponse, "newsletters.0.id"), 'id').toMatch(/^[0-9a-f]{24}$/i);
    expect(getResponseValue(newslettersPostResponse, "newsletters.0.uuid"), 'uuid').toMatch(/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i);
    expect(getResponseValue(newslettersPostResponse, "newsletters.0.created_at"), 'created_at').toMatch(/^\d{4}-\d{2}-\d{2}T/);
    expect(getResponseValue(newslettersPostResponse, "newsletters.1"), 'second newsletter').toBeNull();

    const newslettersNewslettersDeleteResponse = await deleteNewsletter(client, headers, getResponseValue(newslettersPostResponse, "newsletters.0.id"), 204);

    const newslettersNewslettersGetResponse = await getNewsletter(client, headers, getResponseValue(newslettersPostResponse, "newsletters.0.id"), 404);
    expect(getResponseValue(newslettersNewslettersGetResponse, "errors.0.type"), 'error type').toBe("NotFoundError");
    expect(getResponseValue(newslettersNewslettersGetResponse, "errors.1"), 'second error').toBeNull();
});
